  "arguments": "{\"action\":\"read\",\"snapshotId\":\"capture-f3de63bd-9ac4-4736-b16c-cf275ffe8180\",\"query\":\"emitDecoratorMetadata design:paramtypes reflect-metadata experimentalDecorators\",\"segmentIndex\":13}",
