  "arguments": "{\"action\":\"read\",\"query\":\"Deprecated forwardRef ref as prop codemod how to upgrade\",\"snapshotId\":\"capture-73ee2013-b3d7-4ea7-81b3-1ac9b36b3ab1\",\"segmentIndex\":2}",
