  "arguments": "{\"action\":\"read\",\"query\":\"ref as a prop forwardRef function components receive ref\",\"snapshotId\":\"capture-23273981-ad2c-4ecd-8926-d8b98f8b603c\",\"segmentIndex\":1}",
