  "arguments": "{\"action\":\"read\",\"query\":\"forwardRef deprecated New deprecations\",\"snapshotId\":\"capture-73ee2013-b3d7-4ea7-81b3-1ac9b36b3ab1\",\"segmentIndex\":1}",
