  "arguments": "{\"action\":\"read\",\"query\":\"Decorators emit legacy __decorate experimentalDecorators evaluation order\",\"segmentIndex\":0,\"snapshotId\":\"capture-ffc1320f-4df2-49b3-a33e-f5bbe0777fe3\"}",
