  "arguments": "{\"action\":\"read\",\"query\":\"ref as a prop forwardRef no longer necessary class components\",\"snapshotId\":\"capture-19c2e4af-19ca-41ab-b084-708d2741c0db\",\"segmentIndex\":1}",
